/**
 * Full MCP client configuration (used in responses)
 */
export type McpClientConfigWritable = {
    /**
     * Unique identifier for the MCP client
     */
    client_id?: string;
    /**
     * Display name for the MCP client
     */
    name?: string;
    /**
     * Whether this client is available in code mode
     */
    is_code_mode_client?: boolean;
    /**
     * Connection type for MCP client
     */
    connection_type?: 'http' | 'stdio' | 'sse' | 'inprocess';
    /**
     * HTTP or SSE URL (required for HTTP or SSE connections)
     */
    connection_string?: string;
    /**
     * STDIO configuration for MCP client
     */
    stdio_config?: {
        /**
         * Executable command to run
         */
        command?: string;
        /**
         * Command line arguments
         */
        args?: Array<string>;
        /**
         * Environment variables required
         */
        envs?: Array<string>;
    };
    /**
     * TLS configuration for HTTP and SSE connections.
     */
    tls_config?: {
        /**
         * Disable TLS certificate verification. Development/testing only.
         */
        insecure_skip_verify?: boolean;
        /**
         * PEM-encoded CA certificate. Supports env.VAR_NAME syntax for input.
         * Responses return a redacted placeholder rather than the raw PEM value.
         *
         */
        ca_cert_pem?: string;
    };
    /**
     * Authentication type for the MCP connection
     */
    auth_type?: 'none' | 'headers' | 'oauth' | 'per_user_oauth' | 'per_user_headers' | 'token_exchange';
    /**
     * OAuth config ID for OAuth authentication.
     * References the oauth_configs table.
     * Only set when auth_type is "oauth".
     *
     */
    oauth_config_id?: string;
    /**
     * Custom headers to include in requests.
     * Only used when auth_type is "headers".
     *
     */
    headers?: {
        [key: string]: string;
    };
    /**
     * Include-only list for tools.
     * ["*"] => all tools are included
     * [] => no tools are included
     * ["tool1", "tool2"] => include only the specified tools
     *
     */
    tools_to_execute?: Array<string>;
    /**
     * List of tools that can be auto-executed without user approval.
     * Must be a subset of tools_to_execute.
     * ["*"] => all executable tools can be auto-executed
     * [] => no tools are auto-executed
     * ["tool1", "tool2"] => only specified tools can be auto-executed
     *
     */
    tools_to_auto_execute?: Array<string>;
    /**
     * Per-tool cost in USD for execution.
     * Key is the tool name, value is the cost per execution.
     * Example: {"read_file": 0.001, "write_file": 0.002}
     *
     */
    tool_pricing?: {
        [key: string]: number;
    };
    /**
     * When true, this MCP client's tools are accessible to all virtual keys without requiring
     * explicit per-key assignment. All tools are allowed by default. If a virtual key has an
     * explicit MCP config for this client, that config takes precedence and overrides this behaviour.
     *
     */
    allow_on_all_virtual_keys?: boolean;
    /**
     * For `per_user_headers` clients only. The list of header names each end-user
     * must supply via the inline-401 flow. Header values themselves are stored
     * per-user in a separate table (surfaced on `/api/mcp/sessions`).
     *
     */
    per_user_header_keys?: Array<string>;
    /**
     * For `token_exchange` clients only. `client_id` and `client_secret` are
     * redacted in this response.
     *
     */
    token_exchange?: unknown & {
        /**
         * Resource identifier this server is scoped to at the identity provider (e.g. "api://jira-mcp")
         */
        audience: string;
        /**
         * When true, performs the exchange as the SSO login application itself
         * instead of client_id/client_secret below, which are then ignored.
         * Some providers require this: Microsoft Entra ID's on-behalf-of grant
         * only accepts an assertion audienced to the exchanging application,
         * and the SSO login flow always requests a token self-audienced to the
         * SSO application, so a separate exchange application can never
         * receive a usable one.
         *
         */
        use_idp_credentials?: boolean;
        /**
         * The identity-provider application authorized to perform exchanges for
         * this audience — typically a dedicated registration carrying the
         * token-exchange (or on-behalf-of) grant, separate from the SSO login
         * application. Required unless use_idp_credentials is true. Supports
         * env.VAR_NAME and vault.path references. Redacted in API responses.
         *
         */
        client_id?: string;
        /**
         * Secret for the exchange application; omit for public clients. Ignored
         * when use_idp_credentials is true. Supports env.VAR_NAME and
         * vault.path references. Redacted in API responses.
         *
         */
        client_secret?: string;
        /**
         * Optional scopes to request on the exchanged token. Include
         * "offline_access" (where the identity provider supports it) so the
         * retained admin discovery credential gets a refresh token and stays
         * self-renewing.
         *
         */
        scopes?: Array<string>;
        /**
         * Overrides the Authorization Server the exchange request is sent to.
         * Only needed when the audience is registered on a different
         * Authorization Server than the one used for SSO login (e.g. Okta's
         * per-resource Custom Authorization Servers). Leave unset to use the
         * deployment's SSO login issuer, which is correct for providers with a
         * single tenant-wide token endpoint (Entra, Auth0).
         *
         */
        authorization_server_url?: string;
    };
    /**
     * Whether the client is intentionally disabled.
     * When true, the client has no active connection or workers and its tools are not available for inference.
     *
     */
    disabled?: boolean;
};

/**
 * Virtual key configuration
 */
export type VirtualKeyWritable = {
    id: string;
    name: string;
    value: string;
    description?: string;
    is_active: boolean;
    /**
     * Expiry timestamp. Requests using this virtual key are rejected once it passes. Null or absent means the key never expires.
     */
    expires_at?: string | null;
    /**
     * Per-key override for client.delete_expired_virtual_keys. Absent or null inherits the client setting; true or false decide for this key whether the daily cleanup job deletes it once expires_at has passed.
     */
    delete_after_expire?: boolean | null;
    /**
     * When set, the pre-rotation key value continues to authenticate until this timestamp (rotation grace period, configured via client vk_rotation_cooldown). Absent when no grace window is active.
     */
    previous_value_expires_at?: string | null;
    /**
     * Timestamp of the most recent value rotation. Absent if the key has never been rotated.
     */
    rotated_at?: string | null;
    provider_configs: Array<VirtualKeyProviderConfig>;
    mcp_configs: Array<VirtualKeyMcpConfigWritable>;
    team_id?: string;
    customer_id?: string;
    rate_limit_id?: string;
    calendar_aligned: boolean;
    /**
     * When true, this virtual key may use every configured provider. provider_configs still apply as optional per-provider overrides (budgets, rate limits, model allow/blacklists, key selection); a provider without a config gets all models, all keys, and no per-provider limits.
     *
     */
    allow_all_providers?: boolean;
    /**
     * The key's own content-logging decision. Absent or null inherits client.disable_content_logging. true keeps request and response content out of the log store and out of OpenTelemetry export for this key's traffic; other observability connectors follow their own disable_content_logging until they adopt the trace mark. false forces content into the log store even when the client setting is true; observability connectors keep following their own disable_content_logging. When content logging ends up disabled for a request, the log row is still written without content; with client.retain_content_in_object_storage on and an object-storage-backed log store, the full payload is then kept there as hidden content that the API and UI never serve. When client.allow_per_request_content_storage_override is on, the x-bf-disable-content-logging request header still takes precedence over this value for the log store.
     *
     */
    disable_content_logging?: boolean | null;
    team?: TeamWritable;
    customer?: CustomerWritable;
    /**
     * Budget quotas assigned directly to this virtual key
     */
    budgets?: Array<Budget>;
    rate_limit?: RateLimit;
    config_hash: string;
    /**
     * User that created this virtual key, when available
     */
    created_by_user_id?: string;
    created_at: string;
    updated_at: string;
};

